package com.oms.channel.platform;

import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.*;

/** Allowlisted structured snapshots. Credentials and unrecognized free text never reach storage. */
final class PlatformLogSanitizer {
    private static final ObjectMapper JSON=new ObjectMapper();
    private static final Set<String> SECRET=new HashSet<>(Arrays.asList("secret","appsecret","clientsecret","access_token","accesstoken","refresh_token","refreshtoken","token","session","sign","signature","code","state","authorization","secret_cipher","token_cipher","refresh_cipher","password","oaid"));
    private static final Set<String> VALUES=new HashSet<>(Arrays.asList("method","fields","grant_type","refund_id","refund_sn","refund_version","refund_fee","mode","start_time","end_time","page_time","page_refund_id","dispute_id","biz_order_id","bizorder_id","tid","oid","sid","status","num","quantity","actualqty","planqty","sku","skusn","sku_sn","outer_iid","outer_sku_id","exchange_sku","bought_sku","refund_phase","speed_exchange","good_status","modified","created","page_no","page_size","page_results","total_results","has_next","address_id","seller_refuse_reason_id","reason_id","logistics_type","logistics_company_name","logistics_no","express_code","package_code","carrier_code","success","outcome","error_code","sub_code","msg_code","request_id","requestid","trace_id","receipt","receipt_code","expires_in","re_expires_in","deadline","item_code","article_code","start_gmt_modified_time","end_gmt_modifed_time","start_created_time","end_created_time","order_id","order_sn","shipment_sn","exchange_sn","package_id","task_id","simulation","count","shop_id","authorization","subscription","unit","payment","price","refund_status","company_code","channel_id","platform_tid","platform_oid","shipment_line_id","order_line_id","platform_carrier_code","notification_type","num_iid","sku_id","item_id","outer_id","properties","properties_name","approve_status","pic_url","saved","binding_id","binding_revision","product_id","from_sku","to_sku","revision"));
    private static final Set<String> MASK=new HashSet<>(Arrays.asList("mobile","phone","receiver_mobile","receiver_phone","name","receiver_name","nick","seller_nick","taobao_user_nick","title","detailaddress","address","complete_address","receiver_address","return_address","return_contact","contact"));
    static final class Snapshot {final String json;final boolean truncated;Snapshot(String j,boolean t){json=j;truncated=t;}}
    static Snapshot snapshot(Object input){return snapshot(input,Collections.emptySet());}
    static Snapshot snapshot(Object input,Collection<String> forbidden){Set<String> secrets=new HashSet<>(forbidden);Object value=JSON.convertValue(input,Object.class);collect(value,secrets,new int[]{0});boolean[] clipped={false};Object safe=clean(value,0,clipped,secrets);try{String body=JSON.writeValueAsString(safe);if(body.length()>65536)return new Snapshot("{\"notice\":\"脱敏报文超过大小限制，未保存正文\"}",true);return new Snapshot(body,clipped[0]);}catch(Exception e){return new Snapshot("{\"notice\":\"无法记录结构化报文\"}",true);}}
    private static void collect(Object value,Set<String> secrets,int[] visited){if(value==null||++visited[0]>1000)return;if(value instanceof Map){for(Map.Entry<?,?> e:((Map<?,?>)value).entrySet()){String k=String.valueOf(e.getKey()).toLowerCase(Locale.ROOT).replace("_","").replace("-","");Object v=e.getValue();if((SECRET.contains(k)||k.contains("secret")||k.endsWith("token")||k.endsWith("cipher"))&&v instanceof String&&((String)v).length()>=4)secrets.add((String)v);else if(v instanceof Map||v instanceof Collection)collect(v,secrets,visited);}}else if(value instanceof Collection)for(Object v:(Collection<?>)value){if(visited[0]>1000)break;collect(v,secrets,visited);}}
    private static Object clean(Object value,int depth,boolean[] clipped,Set<String> secrets){
        if(depth>12){clipped[0]=true;return "[层级截断]";}
        if(value instanceof Map){Map<String,Object> out=new LinkedHashMap<>();int count=0;for(Map.Entry<?,?> entry:((Map<?,?>)value).entrySet()){if(++count>100){clipped[0]=true;out.put("_notice","字段截断");break;}String key=String.valueOf(entry.getKey());if(key.length()>128){clipped[0]=true;continue;}String normalized=key.toLowerCase(Locale.ROOT),compact=normalized.replace("_","").replace("-","");Object v=entry.getValue();if(SECRET.contains(normalized)||SECRET.contains(compact)||compact.contains("secret")||compact.endsWith("token")||compact.endsWith("cipher")){out.put(key,"[凭据不记录]");continue;}if(MASK.contains(normalized)||MASK.contains(compact)){out.put(key,"[已脱敏]");continue;}if(v instanceof Map||v instanceof Collection){out.put(key,clean(v,depth+1,clipped,secrets));continue;}if(!VALUES.contains(normalized)&&!VALUES.contains(compact)&&!(normalized.matches("[0-9]{1,64}")&&v instanceof Number)){out.put(key,"[字段未记录]");continue;}if(v==null||v instanceof Number||v instanceof Boolean)out.put(key,v);else{String text=String.valueOf(v);for(String secret:secrets)if(secret.length()>=4)text=text.replace(secret,"[凭据不记录]");if(text.length()>512){text=text.substring(0,512)+"[截断]";clipped[0]=true;}out.put(key,text);}}return out;}
        if(value instanceof Collection){List<Object> out=new ArrayList<>();for(Object v:(Collection<?>)value){if(out.size()>=50){clipped[0]=true;break;}out.add(v instanceof Map||v instanceof Collection?clean(v,depth+1,clipped,secrets):"[无字段名值不记录]");}return out;}
        return value==null?null:"[非结构化报文不记录]";
    }
}
